18	
19	import org.springframework.samples.petclinic.model.Owner;
20	
21	/**
22	 * Derives an owner's {@code checkDigit}: the single Luhn check digit (0-9) computed over the digits
23	 * of its customerCode. Kept as a small standalone unit so the response mapper can expose the value
24	 * without growing.
25	 */
26	public final class OwnerCheckDigit {
27	
28	    private OwnerCheckDigit() {
29	    }
30	
31	    public static Integer of(Owner owner) {
32	        String code = owner.getCustomerCode();
33	        return code == null ? null : luhn(code);
34	    }
35	
36	    static int luhn(String s) {
37	        int sum = 0;
38	        boolean dbl = true;
39	        for (int i = s.length() - 1; i >= 0; i--) {
40	            char c = s.charAt(i);
41	            if (c < '0' || c > '9') {
42	                continue;
43	            }
44	            int d = c - '0';
45	            if (dbl && (d *= 2) > 9) {
46	                d -= 9;
47	            }
48	            sum += d;
49	            dbl = !dbl;
50	        }
51	        return (10 - (sum % 10)) % 10;
52	    }
53	}
