27	/**
28	 * Emits an audit trail entry on the dedicated {@code AUDIT} logger whenever a new owner is
29	 * successfully created, carrying the assigned id, customerCode and registrationDate. Kept as
30	 * its own small aspect so this rule stays a self-contained unit rather than growing the
31	 * controller or service.
32	 */
33	@Aspect
34	@Component
35	public class OwnerAuditCreationAdvice {
36	
37	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
38	
39	    @Around("execution(* org.springframework.samples.petclinic.service.ClinicService.saveOwner(..)) && args(owner)")
40	    public Object auditCreation(ProceedingJoinPoint joinPoint, Owner owner) throws Throwable {
41	        boolean created = owner.isNew();
42	        Object result = joinPoint.proceed();
43	        if (created) {
44	            AUDIT.info("owner created id={} customerCode={} registrationDate={}",
45	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
46	        }
47	        return result;
48	    }
49	}
