15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
23	    @Mapping(target = "householdId", expression = "java(java.util.UUID.nameUUIDFromBytes((owner.getLastName() + \"|\" + owner.getAddress()).trim().replaceAll(\"\\\\s+\", \" \").toLowerCase(java.util.Locale.ROOT).getBytes(java.nio.charset.StandardCharsets.UTF_8)).toString())")
24	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerIdentityKey.of(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.rest.advice.OwnerCheckDigit.of(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipLevel", expression = "java(Math.min(3, 1 + (owner.getEmail() != null && !owner.getEmail().isBlank() ? 1 : 0) + (Integer.valueOf(0).equals(owner.getNamesakeCount()) ? 1 : 0)))")
28	    @Mapping(target = "locality", expression = "java(java.util.Map.of(20, \"NSW\", 30, \"VIC\", 40, \"QLD\").getOrDefault(owner.getPostcode() != null && owner.getPostcode().matches(\"[0-9]{4}\") ? Integer.parseInt(owner.getPostcode()) / 100 : -1, java.util.Map.of(\"Sydney\", \"NSW\", \"Melbourne\", \"VIC\", \"Brisbane\", \"QLD\").getOrDefault(owner.getCity(), \"UNKNOWN\")))")
29	    @Mapping(target = "contactPreference", expression = "java(owner.getEmail() != null && !owner.getEmail().isBlank() ? \"EMAIL\" : \"PHONE\")")
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    Owner toOwner(OwnerDto ownerDto);
33	
34	    @Mapping(target = "id", ignore = true)
35	    @Mapping(target = "pets", ignore = true)
36	    Owner toOwner(OwnerFieldsDto ownerDto);
37	
38	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
39	
40	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
41	
42	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
43	        OwnerPageDto ownerPageDto = new OwnerPageDto();
44	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
45	        ownerPageDto.setPage(ownerPage.getNumber());
46	        ownerPageDto.setSize(ownerPage.getSize());
47	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
48	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
49	        return ownerPageDto;
50	    }
51	}
