35	/**
36	 * Rejects an owner whose supplied postcode falls outside the range allowed for its city's
37	 * region (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), answering with a 400. The postcode
38	 * is optional: absent postcodes and cities with no known region are accepted. Kept as its
39	 * own advice so this rule stays a small, self-contained unit.
40	 */
41	@ControllerAdvice
42	@Order(Ordered.HIGHEST_PRECEDENCE)
43	public class OwnerPostcodeValidationAdvice extends RequestBodyAdviceAdapter {
44	
45	    /** Lowest valid postcode per city, region ranges spanning that value plus 99. */
46	    private static final Map<String, Integer> REGION_BASE =
47	        Map.of("Sydney", 2000, "Melbourne", 3000, "Brisbane", 4000);
48	
49	    @Override
50	    public boolean supports(MethodParameter methodParameter, Type targetType,
51	                            Class<? extends HttpMessageConverter<?>> converterType) {
52	        return OwnerFieldsDto.class.equals(targetType);
53	    }
54	
55	    @Override
56	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
57	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
58	        OwnerFieldsDto owner = (OwnerFieldsDto) body;
59	        String postcode = owner.getPostcode();
60	        Integer base = REGION_BASE.get(owner.getCity());
61	        if (postcode != null && base != null && !inRange(postcode, base)) {
62	            throw new InvalidPostcodeException();
63	        }
64	        return body;
65	    }
66	
67	    private boolean inRange(String postcode, int base) {
68	        if (!postcode.matches("[0-9]{4}")) {
69	            return true; // malformed postcodes are left for @Pattern bean validation to reject
70	        }
71	        int value = Integer.parseInt(postcode);
72	        return value >= base && value <= base + 99;
73	    }
74	
75	    @ExceptionHandler(InvalidPostcodeException.class)
76	    @ResponseBody
77	    public ResponseEntity<String> handleInvalidPostcode(InvalidPostcodeException e) {
78	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(e.getMessage());
79	    }
80	
81	    /** Signals a postcode that is out of range for its city's region. */
