26	/**
27	 * Derives an owner's {@code identityKey}, the single value all duplicate detection is based on:
28	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. Kept as a small
29	 * standalone unit so the request advice and the response mapper derive the key identically.
30	 */
31	public final class OwnerIdentityKey {
32	
33	    private OwnerIdentityKey() {
34	    }
35	
36	    static String of(OwnerFieldsDto owner) {
37	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress());
38	    }
39	
40	    public static String of(Owner owner) {
41	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName(), owner.getAddress());
42	    }
43	
44	    static String of(String telephone, String email, String lastName, String address) {
45	        return telephone(telephone) + '|' + email(email) + '|' + householdId(lastName, address);
46	    }
47	
48	    static String telephone(String telephone) {
49	        return OwnerTelephoneNormalizationAdvice.toE164(telephone);
50	    }
51	
52	    static String email(String email) {
53	        return (email == null || email.isBlank()) ? "" : email.strip().toLowerCase(Locale.ROOT);
54	    }
55	
56	    static String householdId(String lastName, String address) {
57	        String normalized = (lastName + "|" + address).trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
58	        return UUID.nameUUIDFromBytes(normalized.getBytes(StandardCharsets.UTF_8)).toString();
59	    }
60	}
